import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
const txt=(x,y,s,n=15)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-family="sans-serif" font-size="${n}">${s}</text>`;
export function showRatePractical(kind='plan',cloud=0,reveal=false){let art='',name='',sub='',desc='';if(kind==='turbidity'){const opacity=Math.max(0,Math.min(100,Number(cloud)||0))/100;name='Keep the endpoint consistent';sub='Cross visibility · illustrative slider';desc='Top view through the same solution depth to a black cross. Increasing illustrative cloudiness reduces cross visibility; sulfur causes turbidity. This slider does not measure a real endpoint.';art=`<rect x="95" y="60" width="250" height="190" rx="16" fill="#f8f6f2"/><path d="M180 110L260 190M260 110L180 190" stroke="#182e44" stroke-width="10"/><circle cx="220" cy="150" r="82" fill="#d4dfe7" fill-opacity="${opacity}" stroke="#b7c8d6" stroke-width="4"/>${txt(220,30,'Same flask · same depth · same cross',16)}${txt(220,280,'Sulfur forms → turbidity increases',16)}`;
}else if(kind==='gas'){name='Measure gas over time';sub='Gas syringe · controlled comparison';desc='Schematic stoppered flask connected to a gas syringe. Illustrative records at20s: A24cm³, B40cm³; both finish60cm³. Same limiting magnesium and excess acid.';art=`<path d="M70 125V90H110V125L145 220Q90 240 35 220Z" fill="#ed8b7822" stroke="#b7c8d6" stroke-width="3"/><path d="M75 88H105" stroke="#f8f6f2" stroke-width="10"/><path d="M90 85V55H240V90" stroke="#b7c8d6" stroke-width="4" fill="none"/><rect x="220" y="85" width="170" height="45" rx="6" fill="#b7c8d622" stroke="#f8f6f2"/><path d="M345 90V125M345 108H415" stroke="#f8f6f2" stroke-width="4"/>${txt(305,157,'Gas syringe',14)}${txt(95,255,'Reacting mixture',13)}${txt(280,205,'At20 s: A24 · B40 cm³',15)}${txt(280,235,'Final: both60 cm³',15)}`;
}else{name=kind==='evaluate'?'Check what the method measures':'One variable. Two methods.';sub='Concentration → evidence → conclusion';desc='Concentration investigation planning: change concentration; compare gas-volume readings or time to consistent turbidity endpoint; keep other conditions fixed, repeat and evaluate.';art=`${txt(220,40,'Change concentration',21)}<path d="M220 65V90M220 90H100V120M220 90H340V120" fill="none" stroke="#ed8b78" stroke-width="3"/><rect x="25" y="125" width="175" height="100" rx="20" fill="#b7c8d622" stroke="#b7c8d6"/><rect x="240" y="125" width="175" height="100" rx="20" fill="#b7c8d622" stroke="#b7c8d6"/>${txt(112,163,'Gas volume',18)}${txt(112,197,'Fixed time intervals',13)}${txt(328,163,'Turbidity',18)}${txt(328,197,'Time to same endpoint',13)}${txt(220,280,kind==='evaluate'?'Repeat · investigate anomalies · improve method':'Control conditions · develop a hypothesis',15)}`;}
renderDiagram(name,sub,`<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="${desc}">${art}</svg><p class="diagram-caption">${kind==='turbidity'?'Symbolic opacity, not a light-scattering model or practical measurement.':'Apparatus/data are illustrative. Follow the supervised school method.'}</p>`,reveal?'REASONING CHECKED · PRACTICAL PREPARATION':'REQUIRED PRACTICAL PREPARATION · NOT A LAB RECORD');}
